from datetime import date

APPROVED_CALENDARS = {"team-cal"}
ALLOWED = {"calendar_id", "date", "title"}

def check_call(args, user_confirmed):
    if set(args) != ALLOWED:
        return f"reject: fields {sorted(set(args) ^ ALLOWED)}"
    if args["calendar_id"] not in APPROVED_CALENDARS:
        return "reject: calendar not approved"
    try:
        date.fromisoformat(args["date"])
    except (TypeError, ValueError):
        return "reject: bad date"
    if "http" in args["title"].lower():
        return "reject: no links in title"
    if not user_confirmed:
        return "hold: ask user to confirm"             # no mutation without a yes.
    return "execute (logged)"

ok = {"calendar_id": "team-cal", "date": "2026-10-01", "title": "Standup"}
print(check_call(ok, user_confirmed=False))           # hold
print(check_call(ok, user_confirmed=True))            # execute (logged)
print(check_call({**ok, "share_with": "attacker@example.com"}, True))   # reject
```

